 void search(){String q=search.getText().toString().trim();if(q.isEmpty())return;((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);search.clearFocus();navigate("https://m.youtube.com/results?search_query="+Uri.encode(q));}
 void navigate(String next){if(!YouTubeBrowser.url(next)||isFinishing())return;if(!TunnelStateRepository.on()){status.setText(tr("Подключение YouTube прервано","YouTube connection interrupted"));return;}url=next;if(web==null)createWeb();YouTubeWebRoute.apply(()->{if(web!=null&&!isFinishing())web.loadUrl(url);},this::routeUnavailable);}
 void routeUnavailable(){if(web!=null)web.stopLoading();status.setText(tr("Обновите Android System WebView для просмотра YouTube","Update Android System WebView to watch YouTube"));}
 void choose(){if(starting||isFinishing())return;if(!YouTubeWebRoute.supported()){routeUnavailable();return;}if(!MediaService.configured(this)){status.setText(tr("Подключение YouTube пока недоступно","YouTube connection is not available yet"));return;}permit();}
 void consent(){choose();}
 void permit(){try{Intent request=VpnService.prepare(this);if(request==null)startLocal(false);else{permission=true;startActivityForResult(request,VPN);}}catch(Exception e){status.setText(tr("Android не разрешил запуск локального режима","Android could not start local mode"));}}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==VPN){permission=false;if(result==RESULT_OK)startLocal(false);else{local=false;status.setText(tr("Для просмотра разрешите соединение Oldi","Allow the Oldi connection to watch"));}}}
 void startLocal(boolean restart){if(starting||isFinishing())return;local=true;starting=true;lastRestart=SystemClock.elapsedRealtime();int token=++attempt;status.setText(tr("Подключаем YouTube…","Connecting YouTube…"));if(restart)LocalTunnelService.stop(this);ui.postDelayed(()->startAfterStop(token,SystemClock.elapsedRealtime()+6000,restart),restart?200:0);}
 void startAfterStop(int token,long deadline,boolean restart){if(token!=attempt||isFinishing())return;if(restart&&(TunnelStateRepository.on()||NetworkDiagnostics.otherVpn(this))){if(SystemClock.elapsedRealtime()<deadline){ui.postDelayed(()->startAfterStop(token,deadline,true),150);return;}starting=false;status.setText(tr("Предыдущий VPN ещё отключается. Повторите.","The previous VPN is still disconnecting. Retry."));return;}try{LocalTunnelService.start(this);awaitTunnel(token,SystemClock.elapsedRealtime()+65000);}catch(Exception e){starting=false;status.setText(tr("Локальный модуль не запустился","Local module failed to start"));}}
 void awaitTunnel(int token,long deadline){if(token!=attempt||isFinishing())return;if(TunnelStateRepository.on()){starting=false;connectionLabel();navigate(url);return;}if(SystemClock.elapsedRealtime()-lastRestart>1500&&TunnelStateRepository.state.equals("OFF")&&!TunnelStateRepository.error.isEmpty()){starting=false;status.setText(tr("Не удалось подключить YouTube. Код: ","Could not connect YouTube. Code: ")+TunnelStateRepository.error);return;}if(SystemClock.elapsedRealtime()<deadline)ui.postDelayed(()->awaitTunnel(token,deadline),150);else{starting=false;status.setText(tr("Не удалось подключить YouTube. ⋮ → Проверить соединение","Could not start local mode. ⋮ → Diagnostics"));}}
 void connectionLabel(){if(starting)return;status.setText(local&&TunnelStateRepository.on()?tr("YouTube · соединение Oldi","YouTube · Oldi connection"):tr("Подключаем YouTube…","Connecting YouTube…"));}
 void information(){diagnostics();}
 void menu(){String[] options={tr("Обновить","Reload"),tr("История просмотренного","Watch history"),tr("Избранные ролики","Favorite videos"),tr("Добавить в избранное","Toggle favorite"),tr("Отправить ролик в чат","Send video to chat"),tr("Смотреть в плеере","Watch in player"),tr("Мой аккаунт YouTube","My YouTube account"),tr("Проверить соединение","Check connection")};new AlertDialog.Builder(this).setItems(options,(d,w)->{if(w==0)choose();else if(w==1||w==2)startActivity(new Intent(this,MainActivity.class).putExtra("video_tab",w==1?"history":"favorite").addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));else if(w==6)googleSignIn();else if(w==7)diagnostics();else{YouTubeLinkDetector.Target target=YouTubeLinkDetector.parse(url);if(target==null||target.videoId.isEmpty()){status.setText(tr("Сначала откройте видео","Open a video first"));return;}if(w==3&&library!=null){work.execute(()->{try{library.toggle(target.videoId,"favorite");boolean saved=library.get(target.videoId).optBoolean("favorite");runOnUiThread(()->Toast.makeText(this,tr(saved?"Ролик в избранном":"Ролик убран из избранного",saved?"Video saved":"Video removed"),Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->status.setText(tr("Не удалось сохранить ролик","Could not save video")));}});}else if(w==4)startActivity(new Intent(this,MainActivity.class).putExtra("share_youtube",target.url()).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));else if(w==5)OldiYouTubePlayer.open(this,target,"YouTube");}}).show();}
 void rememberPlayback(){if(web==null||!loaded||library==null)return;web.evaluateJavascript("JSON.stringify({url:location.href,title:document.title,time:document.querySelector('video')?.currentTime||0,duration:document.querySelector('video')?.duration||0,playing:!!document.querySelector('video')&&!document.querySelector('video').paused})",raw->{if(isDestroyed()||raw==null||raw.length()>5000)return;try{Object value=new org.json.JSONTokener(raw).nextValue();if(!(value instanceof String))return;org.json.JSONObject state=new org.json.JSONObject((String)value);YouTubeLinkDetector.Target target=YouTubeLinkDetector.parse(state.optString("url"));if(target==null||target.videoId.isEmpty())return;double position=state.optDouble("time"),duration=state.optDouble("duration"),watched=state.optBoolean("playing")&&target.videoId.equals(observedVideo)?Math.min(3,Math.max(0,position-observedPosition)):0;observedVideo=target.videoId;observedPosition=position;if(YouTubeBrowser.url(state.optString("url")))url=state.optString("url");work.execute(()->{try{library.update(target.videoId,state.optString("title"),position,duration,watched);}catch(Exception ignored){}});}catch(Exception ignored){}});}
 void strategies(){String[] values={"auto","split","disorder","fake4","fake8"};String[] names={tr("Автоматически · 5 вариантов","Automatic · 5 strategies"),tr("Разделение TLS","TLS splitting"),tr("Порядок пакетов","Packet order"),tr("Дополнительный режим 1","Additional mode 1"),tr("Дополнительный режим 2","Additional mode 2")};new AlertDialog.Builder(this).setTitle(tr("Подобрать соединение","Find connection")).setItems(names,(d,w)->{Notices.prefs(this).edit().putString("youtube_dpi_strategy",values[w]).apply();if(VpnService.prepare(this)==null)startLocal(true);else consent();}).setNeutralButton(tr("Что проверить","What to check"),(d,w)->information()).show();}
