 final Runnable heartbeat=new Runnable(){public void run(){if(!foreground)return;rememberPlayback();if(local){if(TunnelStateRepository.on())LocalTunnelService.touch(YouTubeHubActivity.this);else if(!starting&&!permission&&NetworkDiagnostics.physical(YouTubeHubActivity.this)!=null&&SystemClock.elapsedRealtime()-lastRestart>10000){startLocal(false);}}ui.postDelayed(this,2000);}};
 protected void onResume(){super.onResume();if(browserPaused){browserActive=false;browserPaused=false;LocalTunnelService.browser(this,false);connectionLabel();}foreground=true;if(web!=null)web.onResume();if(local&&TunnelStateRepository.on())YouTubeWebRoute.apply(()->{});ui.post(heartbeat);}
